// {표기|읽기} → <ruby>
// v6.4: 후리가나 마크업이 없는 챕터에서도 한자를 탭해 뜻을 볼 수 있게, 맨 한자 덩어리도 .rd-w 로 감싼다
//   (rdTapSentence 가 .rd-w 만 단어팝업으로 잡기 때문에, 예전엔 후리가나 없는 책은 탭해도 반응이 없었다)
function rdRubyHtml(t){
  const parts = String(t).split(/(\{[^|{}]+\|[^|{}]+\})/);
  return parts.map(p=>{
    if(p.length>2 && p[0]==="{" && p[p.length-1]==="}"){
      const m = /^\{([^|{}]+)\|([^|{}]+)\}$/.exec(p);
      if(!m) return p;
      const a=m[1], b=m[2];
      return `<ruby class="rd-w" data-w="${a}" data-r="${b}"><rb>${a}</rb><rt>${b}</rt></ruby>`;
    }
    // 루비 밖의 맨 한자(々 포함) 덩어리를 탭 가능한 span 으로 감싼다. data-r="" 로 두면 rdLookup 가 표기만으로 뜻을 찾는다.
    return p.replace(/[一-鿿々]+/g, k=>`<span class="rd-w" data-w="${k}" data-r="">${k}</span>`);
  }).join("");
}
